class MyLiteLlm(CustomLLM):
    def __init__(self):
        super().__init__()
        load_dotenv()
        self._endpoint = os.getenv("ENDPOINT")
        self._key = os.getenv("KEY")
        self._model = os.getenv("MODEL")
        self._api_version = os.getenv("API_VERSION")
        self._supports_tool_calls = True

    def process_request(self, *args, **kwargs) -> litellm.ModelResponse:
        messages = kwargs.get("messages", [])
        tools = kwargs.get("tools", None)
        tool_choice = kwargs.get("tool_choice", None)

        if not messages:
            raise ValueError("The 'messages' parameter is required.")

        headers = {
            "Content-Type": "application/json",
            "api-key": self._key
        }

        query_params = {
            "api-version": self._api_version
        }

        body = {
            "messages": messages,
            "model": self._model,
            "temperature": kwargs.get("temperature", 0.7),
            "max_tokens": kwargs.get("max_tokens", 800),
        }

        if tools:
            body["tools"] = tools
            if tool_choice:
                body["tool_choice"] = tool_choice
            else:
                body["tool_choice"] = "auto"

        full_path = f"{self._endpoint}/openai/deployments/{self._model}/chat/completions"

        response = requests.post(
            full_path,
            headers=headers,
            params=query_params,
            json=body
        )
        response.raise_for_status()
        api_response_data = response.json()

        choices = []
        for choice in api_response_data.get("choices", []):
            message_data = choice.get("message", {})

            tool_calls = None
            if "tool_calls" in message_data and message_data["tool_calls"]:
                tool_calls = []
                for tool_call in message_data["tool_calls"]:
                    tool_calls.append(
                        litellm.utils.ToolCall(
                            id=tool_call.get("id"),
                            type=tool_call.get("type"),
                            function=litellm.utils.Function(
                                name=tool_call["function"]["name"],
                                arguments=tool_call["function"]["arguments"]
                            )
                        )
                    )

            choices.append(
                litellm.Choices(
                    finish_reason=choice.get("finish_reason"),
                    index=choice.get("index"),
                    message=litellm.Message(
                        content=message_data.get("content"),
                        role=message_data.get("role"),
                        tool_calls=tool_calls
                    ),
                )
            )

        model_response = ModelResponse(
            id=api_response_data.get("id"),
            choices=choices,
            model=self._model,
            usage=litellm.Usage(
                prompt_tokens=api_response_data.get("usage", {}).get("prompt_tokens", 0),
                completion_tokens=api_response_data.get("usage", {}).get("completion_tokens", 0),
                total_tokens=api_response_data.get("usage", {}).get("total_tokens", 0),
            )
        )
        return model_response

    def completion(self, *args, **kwargs) -> litellm.ModelResponse:
        return self.process_request(*args, **kwargs)

    async def acompletion(self, *args, **kwargs) -> litellm.ModelResponse:
        return self.process_request(*args, **kwargs)

