    def normalize_money(text):
        if not text:
            return None
        m = re.search(r'\$[\d,]+(?:\.\d+)?', text)
        return m.group(0) if m else text.strip()

    def get_value_by_label(scope, label_text):
        xpaths = [
            f".//*[self::div or self::span or self::p or self::dt][contains(translate(normalize-space(.), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'), '{label_text.lower()}')]/following::*[self::div or self::span or self::p or self::dd][1]",
            f".//*[contains(translate(normalize-space(.), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'), '{label_text.lower()}')]/ancestor::*[self::li or self::div][1]//*[self::div or self::span or self::p][last()]",
        ]
        for xp in xpaths:
            try:
                el = scope.find_element(By.XPATH, xp)
                txt = el.text.strip()
                if txt and label_text.lower() not in txt.lower():
                    return normalize_money(txt)
            except NoSuchElementException:
                pass
        return None

    def scrape_listing(driver, url):
        driver.get(url)
        wait = WebDriverWait(driver, 20)

        try:
            wait.until(EC.presence_of_element_located((By.TAG_NAME, "body")))
        except TimeoutException:
            return {"url": url, "error": "page load timeout"}

        labels = {
            "rent_estimate": "rent zestimate",
            "principal_interest": "principal and interest",
            "property_taxes": "property taxes",
            "home_insurance": "home insurance",
            "hoa_fees": "hoa fees",
            "mortgage_insurance": "mortgage insurance",
        }

        result = {"url": url}
        root = driver.find_element(By.TAG_NAME, "body")

        for key, label in labels.items():
            result[key] = get_value_by_label(root, label)

        return result

    options = Options()
    options.add_argument("--headless=new")
    options.add_argument("--window-size=1600,1200")
    options.add_argument("--disable-blink-features=AutomationControlled")

    driver = webdriver.Chrome(options=options)
