    import xml.etree.ElementTree as ET
    from pathlib import Path

    import cairosvg  # VERSION=2.7.1

    def local_name(tag):
        return tag.split('}', 1)[-1] if '}' in tag else tag

    def parse_style(style_text):
        result = {}
        if not style_text:
            return result
        for part in style_text.split(';'):
            if ':' in part:
                k, v = part.split(':', 1)
                result[k.strip()] = v.strip()
        return result

    def style_to_text(style_dict):
        return ';'.join(f'{k}:{v}' for k, v in style_dict.items())

    def set_fill_on_element(elem, color):
        if 'fill' in elem.attrib:
            elem.set('fill', color)
            return True

        style = parse_style(elem.get('style'))
        if 'fill' in style:
            style['fill'] = color
            elem.set('style', style_to_text(style))
            return True

        style['fill'] = color
        elem.set('style', style_to_text(style))
        return True

    def find_by_id(root, object_id):
        for elem in root.iter():
            if elem.get('id') == object_id:
                return elem
        return None

    def recolor_svg(svg_input_path, object_id, color, svg_output_path=None, png_output_path=None, pdf_output_path=None):
        tree = ET.parse(svg_input_path)
        root = tree.getroot()

        target = find_by_id(root, object_id)
        if target is None:
            raise ValueError(f'No SVG element found with id="{object_id}"')

        set_fill_on_element(target, color)

        svg_bytes = ET.tostring(root, encoding='utf-8', xml_declaration=True)

        if svg_output_path:
            Path(svg_output_path).write_bytes(svg_bytes)

        if png_output_path:
            cairosvg.svg2png(bytestring=svg_bytes, write_to=str(png_output_path))

        if pdf_output_path:
            cairosvg.svg2pdf(bytestring=svg_bytes, write_to=str(pdf_output_path))

    def create_example_svg(path):
        svg = """<?xml version="1.0" encoding="UTF-8"?>
<svg width="200" height="200" viewBox="0 0 200 200"
     xmlns="http://www.w3.org/2000/svg" version="1.1">
  <rect id="background" x="0" y="0" width="200" height="200" fill="#ffffff"/>
  <circle id="target_shape" cx="100" cy="100" r="70" fill="#ff0000" stroke="#000000" stroke-width="4"/>
  <text id="label" x="100" y="108" text-anchor="middle" font-size="24" fill="#000000">Demo</text>
</svg>
"""
        Path(path).write_text(svg, encoding='utf-8')

    base_dir = Path.cwd() / "svg_color_output"
    base_dir.mkdir(parents=True, exist_ok=True)

    input_svg = base_dir / "input.svg"
    if not input_svg.exists():
        create_example_svg(input_svg)

    colors = [
        "#e63946",
        "#457b9d",
        "#2a9d8f",
        "#f4a261",
        "#6a4c93",
